CREATE FUNCTION public.create_invited_profile(_user_id uuid,_org_id uuid,_email text,_first text,_last text,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Trusted account service required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=_org_id) OR _role IS NULL THEN RAISE EXCEPTION 'Invalid company or role'; END IF; UPDATE public.profiles SET org_id=_org_id WHERE user_id=_user_id AND org_id IS NULL; UPDATE public.notification_settings SET org_id=_org_id WHERE user_id=_user_id AND org_id IS NULL; UPDATE public.user_roles SET org_id=_org_id,role=_role WHERE user_id=_user_id AND org_id IS NULL; END $$; REVOKE ALL ON FUNCTION public.create_invited_profile(uuid,uuid,text,text,text,public.app_role) FROM PUBLIC,authenticated,anon; GRANT EXECUTE ON FUNCTION public.create_invited_profile(uuid,uuid,text,text,text,public.app_role) TO service_role;
CREATE OR REPLACE FUNCTION public.enforce_company_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jsonb:=to_jsonb(NEW); related uuid; ref record; employee_field text; caller_org uuid:=public.current_org_id(); BEGIN IF TG_OP='UPDATE' AND NEW.org_id IS DISTINCT FROM OLD.org_id AND NOT(OLD.org_id IS NULL AND auth.role()='service_role') THEN RAISE EXCEPTION 'Company assignment cannot be changed'; END IF; IF TG_TABLE_NAME NOT IN ('profiles','employee_records') THEN employee_field:=CASE WHEN j ? 'employee_key' THEN 'employee_key' WHEN j ? 'submitted_by' THEN 'submitted_by' WHEN j ? 'user_id' THEN 'user_id' ELSE NULL END; IF employee_field IS NOT NULL AND j->>employee_field IS NOT NULL THEN related:=public.employee_org_id((j->>employee_field)::uuid); IF related IS NULL AND TG_TABLE_NAME NOT IN ('user_roles','notification_settings') THEN RAISE EXCEPTION 'Employee company is required'; END IF; IF NEW.org_id IS NULL THEN NEW.org_id:=related; ELSIF NEW.org_id IS DISTINCT FROM related THEN RAISE EXCEPTION 'Employee belongs to another company'; END IF; END IF; END IF; IF NEW.org_id IS NULL THEN NEW.org_id:=caller_org; END IF; IF NEW.org_id IS NULL AND TG_TABLE_NAME NOT IN ('profiles','user_roles','notification_settings') THEN RAISE EXCEPTION 'Company membership required'; END IF; IF auth.uid() IS NOT NULL AND coalesce(auth.role(),'')<>'service_role' AND NEW.org_id IS DISTINCT FROM caller_org THEN RAISE EXCEPTION 'Company access denied'; END IF; FOR ref IN SELECT * FROM (VALUES('site_id','client_sites'),('project_id','projects'),('crew_id','crews'),('equipment_id','equipment'),('creditor_id','creditors'),('payroll_run_id','payroll_runs'),('invoice_id','client_invoices'),('applicant_id','applicants'),('geofence_zone_id','geofence_zones')) v(key,t) LOOP IF j->>ref.key IS NOT NULL THEN EXECUTE format('SELECT org_id FROM public.%I WHERE id=$1',ref.t) INTO related USING (j->>ref.key)::uuid; IF related IS NULL OR related IS DISTINCT FROM NEW.org_id THEN RAISE EXCEPTION 'Related record belongs to another company'; END IF; END IF; END LOOP; RETURN NEW; END $$;
CREATE FUNCTION public.audit_company_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jsonb; o uuid; BEGIN j:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; o:=(j->>'org_id')::uuid; IF o IS NOT NULL THEN INSERT INTO public.audit_logs(org_id,employee_id,action,details) VALUES(o,auth.uid(),TG_TABLE_NAME||':'||lower(TG_OP),jsonb_build_object('record_id',j->>'id','actor',auth.uid())); END IF; RETURN NULL; END $$;
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['profiles','employee_records','user_roles','user_workspace_access','payroll_runs','employee_documents','clock_punches','company_settings'] LOOP EXECUTE format('CREATE TRIGGER audit_company_changes AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_company_changes()',tbl); END LOOP; END $$;
-- Anonymous clients use the code-validated portal RPC, never direct tenant table reads.
CREATE POLICY no_anonymous_company_data ON public.client_portal_access AS RESTRICTIVE FOR SELECT TO anon USING(false);
-- Prevent direct location probes against other companies; internal validated clock service remains supported.
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='verify_guard_location'; d:=replace(d,'WHERE id = _site_id;','WHERE id = _site_id AND (auth.role()=''service_role'' OR org_id=public.current_org_id());'); EXECUTE d; END $$;